import React, { useState } from "react";
import axios from "axios";
import "bootstrap/dist/css/bootstrap.min.css";

axios.defaults.withCredentials = true;

function Login() {
    const [data, setData] = useState({
        email: "",
        password: "",
    });

    const handleChange = (e) => {
        setData({ ...data, [e.target.name]: e.target.value });
    };

    const handleLogin = async (e) => {
        e.preventDefault();
        try {
            const res = await axios.post("http://localhost:3002/login", data);
            alert(res.data.message);

            localStorage.setItem("user", JSON.stringify(res.data.user));

            window.location.href = "/dashboard"; // redirect to protected page
        } catch (err) {
            alert("Invalid credentials — try again!");
        }
    };

    return (
        <div className="container d-flex justify-content-center align-items-center" style={{ minHeight: "100vh" }}>
            <div className="card shadow p-4" style={{ maxWidth: "450px", width: "100%" }}>
                <h3 className="text-center mb-4 text-primary fw-bold">Login to Your Account</h3>

                <form onSubmit={handleLogin}>
                    <div className="mb-3">
                        <label className="form-label fw-semibold">Email Address</label>
                        <input
                            type="email"
                            name="email"
                            className="form-control"
                            placeholder="Enter Email"
                            onChange={handleChange}
                            required
                        />
                    </div>

                    <div className="mb-3">
                        <label className="form-label fw-semibold">Password</label>
                        <input
                            type="password"
                            name="password"
                            className="form-control"
                            placeholder="Enter Password"
                            onChange={handleChange}
                            required
                        />
                    </div>

                    <button type="submit" className="btn btn-primary w-100 fw-semibold">
                        Login
                    </button>
                </form>

                <p className="text-center mt-3">
                    Don't have an account?{" "}
                    <a href="/signup" className="text-primary fw-semibold" style={{ textDecoration: "none" }}>
                        Create one
                    </a>
                </p>
            </div>
        </div>
    );
}

export default Login;
